3	const { Router } = require('express');
4	const fs = require('fs');
5	const path = require('path');
6	const os = require('os');
7	const matter = require('gray-matter');
8	const { rateLimit } = require('../middleware/rateLimit');
9	const { validateName } = require('../lib/validators');
10	const { atomicWriteText, atomicWriteJson, ensureDir } = require('../lib/atomicIo');
11	const db = require('../db');
12	
13	const router = Router();
14	
15	const HOME = os.homedir();
16	const CLAUDE_DIR = path.join(HOME, '.claude');
17	const TRAINING_DIR = path.join(CLAUDE_DIR, 'training');
18	
19	function loadTraining(agentName) { return db.loadTraining(agentName); }
20	function saveTraining(agentName, data) { db.saveTraining(agentName, data); }
21	
22	// GET /api/training/:name
23	router.get('/training/:name', validateName, (req, res) => {
24	  res.json(loadTraining(req.params.name));
25	});
26	
27	// POST /api/training/:name
28	router.post('/training/:name', validateName, rateLimit('write'), (req, res) => {
29	  const { issue, correction } = req.body;
30	  if (!issue || !correction) return res.status(400).json({ error: 'issue and correction are required' });
31	  const data = loadTraining(req.params.name);
32	  const entry = {
33	    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
34	    timestamp: new Date().toISOString(),
35	    issue,
36	    correction,
37	    status: 'active',
38	  };
39	  data.push(entry);
40	  saveTraining(req.params.name, data);
41	  res.json(entry);
42	});
43	
44	// PUT /api/training/:name/:id
45	router.put('/training/:name/:id', validateName, rateLimit('write'), (req, res) => {
46	  const data = loadTraining(req.params.name);
47	  const idx = data.findIndex(e => e.id === req.params.id);
48	  if (idx === -1) return res.status(404).json({ error: 'Correction not found' });
49	  const { issue, correction, status } = req.body;
50	  if (issue) data[idx].issue = issue;
51	  if (correction) data[idx].correction = correction;
52	  if (status) data[idx].status = status;
53	  saveTraining(req.params.name, data);
54	  res.json(data[idx]);
55	});
56	
57	// DELETE /api/training/:name/:id
58	router.delete('/training/:name/:id', validateName, rateLimit('write'), (req, res) => {
59	  let data = loadTraining(req.params.name);
60	  const before = data.length;
61	  data = data.filter(e => e.id !== req.params.id);
62	  if (data.length === before) return res.status(404).json({ error: 'Correction not found' });
63	  saveTraining(req.params.name, data);
64	  res.json({ ok: true });
65	});
66	
67	// POST /api/training/:name/bake
68	router.post('/training/:name/bake', validateName, rateLimit('write'), (req, res) => {
69	  const agentName = req.params.name;
70	  const corrections = loadTraining(agentName);
71	  const active = corrections.filter(c => c.status === 'active');
72	  if (active.length === 0) return res.status(400).json({ error: 'No active corrections to bake' });
73	
74	  const agentPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
75	  if (!fs.existsSync(agentPath)) return res.status(404).json({ error: 'Agent not found' });
76	
77	  const content = fs.readFileSync(agentPath, 'utf-8');
78	  const { data, content: body } = matter(content);
79	
80	  const trainingSection = '\n\n## Baked Training Corrections\n\n' +
81	    active.map((c, i) => `${i + 1}. **${c.issue}** → ${c.correction}`).join('\n') + '\n';
82	
83	  const newBody = body.trimEnd() + trainingSection;
84	  const newContent = matter.stringify(newBody, data);
85	  atomicWriteText(agentPath, newContent);
86	
87	  const archivePath = path.join(TRAINING_DIR, agentName + '.archived.json');
88	  let archive = [];
89	  try { if (fs.existsSync(archivePath)) archive = JSON.parse(fs.readFileSync(archivePath, 'utf-8')); } catch {}
90	  archive.push(...active.map(c => ({ ...c, bakedAt: new Date().toISOString() })));
91	  ensureDir(TRAINING_DIR);
92	  atomicWriteJson(archivePath, archive);
93	
94	  saveTraining(agentName, corrections.filter(c => c.status !== 'active'));
95	
96	  res.json({ ok: true, baked: active.length });
97	});
98	
99	module.exports = router;
100

