21	// ── Docs context cache ──────────────────────────────────────────────────────
22	let _docsCache = null;
23	let _docsCacheTime = 0;
24	const DOCS_CACHE_TTL = 5 * 60 * 1000;
25	
26	function loadDocsContext() {
27	  const now = Date.now();
28	  if (_docsCache && (now - _docsCacheTime) < DOCS_CACHE_TTL) return _docsCache;
29	  try {
30	    if (!fs.existsSync(DOCS_PATH)) { _docsCache = ''; return ''; }
31	    const files = fs.readdirSync(DOCS_PATH).filter(f => f.endsWith('.md')).sort();
32	    const parts = files.map(f => {
33	      const content = fs.readFileSync(path.join(DOCS_PATH, f), 'utf-8').trim();
34	      return `### ${f}\n${content}`;
35	    });
36	    _docsCache = parts.join('\n\n---\n\n');
37	    _docsCacheTime = now;
38	    return _docsCache;
39	  } catch { return ''; }
40	}
