42	function buildAiSystemPrompt(clientSystem) {
43	  const base = clientSystem || 'You are an expert Claude Code assistant helping users write and improve their Claude agents, commands, rules, and CLAUDE.md files. Be concise and practical.';
44	  const docs = loadDocsContext();
45	  if (!docs) return base;
46	  return `${base}
47	
48	---
49	
50	## Polyglot Documentation (your knowledge base — use this to answer questions)
51	
52	${docs}
53	
54	---
55	
56	When a user asks how something works, what to add, or how to use any feature, answer using the documentation above. Be concise and practical.`;
57	}
