156	router.post('/ai/apply', rateLimit('write'), (req, res) => {
157	  const { filePath, content } = req.body;
158	  if (!filePath || typeof filePath !== 'string' || typeof content !== 'string') {
159	    return res.status(400).json({ error: 'filePath and content required' });
160	  }
161	  if (filePath.includes('\0')) return res.status(400).json({ error: 'Invalid path' });
162	
163	  const resolved = path.resolve(filePath.replace(/^~/, HOME));
