169	  const allowed = allowedRoots.some(root =>
170	    resolved === root || resolved.startsWith(root + path.sep)
171	  );
172	  if (!allowed) return res.status(403).json({ error: 'Path outside allowed directories' });
173	
174	  const basename = path.basename(resolved).toLowerCase();
175	  const BLOCKED_FILES = ['.env', '.env.local', '.env.production', 'credentials.json', 'id_rsa', 'id_ed25519'];
176	  if (BLOCKED_FILES.includes(basename)) {
177	    return res.status(403).json({ error: 'Cannot write to sensitive files' });
